package com.djibtout.backend.entity;
import jakarta.persistence.*;import org.hibernate.annotations.CreationTimestamp;import java.math.BigDecimal;import java.time.LocalDateTime;
@Entity @Table(name="seller_settlements",uniqueConstraints=@UniqueConstraint(columnNames="fulfillment_id")) public class SellerSettlement{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@OneToOne(optional=false)@JoinColumn(name="fulfillment_id") private SellerFulfillment fulfillment;@ManyToOne(optional=false)@JoinColumn(name="seller_id") private User seller;@Column(nullable=false,precision=10,scale=2) private BigDecimal grossAmount;@Column(nullable=false,precision=10,scale=2) private BigDecimal commissionAmount;@Column(nullable=false,precision=10,scale=2) private BigDecimal netAmount;@Enumerated(EnumType.STRING)@Column(nullable=false) private SellerSettlementStatus status=SellerSettlementStatus.AVAILABLE;@CreationTimestamp private LocalDateTime createdAt;private LocalDateTime paidAt;
 public Long getId(){return id;}public SellerFulfillment getFulfillment(){return fulfillment;}public void setFulfillment(SellerFulfillment v){fulfillment=v;}public User getSeller(){return seller;}public void setSeller(User v){seller=v;}public BigDecimal getGrossAmount(){return grossAmount;}public void setGrossAmount(BigDecimal v){grossAmount=v;}public BigDecimal getCommissionAmount(){return commissionAmount;}public void setCommissionAmount(BigDecimal v){commissionAmount=v;}public BigDecimal getNetAmount(){return netAmount;}public void setNetAmount(BigDecimal v){netAmount=v;}public SellerSettlementStatus getStatus(){return status;}public void setStatus(SellerSettlementStatus v){status=v;}public LocalDateTime getCreatedAt(){return createdAt;}public LocalDateTime getPaidAt(){return paidAt;}public void setPaidAt(LocalDateTime v){paidAt=v;}
}
